import sys, subprocess, json, os
# Check if required packages are installed; install if missing
required = ['numpy', 'pandas', 'scipy']
missing = []
for pkg in required:
    try:
        __import__(pkg)
    except ImportError:
        missing.append(pkg)
if missing:
    subprocess.check_call([sys.executable, '-m', 'pip', 'install', '--quiet'] + missing)
